const names=["tofacitinib","baricitinib","upadacitinib","ruxolitinib","fedratinib","abrocitinib","deucravacitinib","ritlecitinib","filgotinib","peficitinib","pacritinib","momelotinib","delgocitinib","oclacitinib"];
const rows=[];
for(const n of names){
 try{const d=await tools.chembl({action:"drug",query:n});
 const x=(d.drugs||[])[0];
 if(!x){rows.push({drug:n,note:"no ChEMBL drug record"});continue;}
 const r=await tools.chembl({action:"mechanism",chemblId:x.moleculeChemblId,idType:"compound",limit:20});
 rows.push({drug:n,id:x.moleculeChemblId,phase:x.maxPhase,appr:x.firstApproval,ind:x.indication,mech:(r.mechanisms||[]).map(m=>JSON.stringify(m))});
 }catch(e){rows.push({drug:n,err:e.message})}
}
text(JSON.stringify(rows,null,1));

